// Parse query parameters
const query = $input.first().json.query || {};

const params = {
  company_id: query.company_id || null,
  status: query.status || null,
  date_from: query.date_from || null,
  date_to: query.date_to || null,
  page: parseInt(query.page) || 1,
  limit: Math.min(parseInt(query.limit) || 50, 200),
  include_driver_details: query.include_driver_details === 'true'
};

if (!params.company_id) {
  throw new Error('company_id is required');
}

params.offset = (params.page - 1) * params.limit;

return { params };

const deliveries = $input.first().json;
const { params } = $('Format Delivery Params').first().json;

// Format the response
const formattedDeliveries = deliveries.map(delivery => ({
  id: delivery.id,
  order_number: delivery.order_number,
  customer: {
    name: delivery.customer_name,
    phone: delivery.customer_phone,
    address: delivery.delivery_address
  },
  order_details: {
    total_amount: parseFloat(delivery.total_amount),
    quantity: parseInt(delivery.quantity),
    status: delivery.status,
    created_at: delivery.created_at
  },
  driver: delivery.driver_info,
  carts: delivery.carts || []
}));

const totalCount = deliveries[0]?.total_count || 0;
const totalPages = Math.ceil(totalCount / params.limit);

return {
  success: true,
  data: {
    deliveries: formattedDeliveries,
    pagination: {
      current_page: params.page,
      per_page: params.limit,
      total: totalCount,
      total_pages: totalPages
    }
  },
  metadata: {
    timestamp: new Date().toISOString(),
    company_id: params.company_id
  }
};
